/* ---------- Routing ---------- */
/* Each page is its own file (built by build.js). Links to another page load it normally;
   links within the same page glide to their section. */
const PAGE = document.body.dataset.page || 'home';
function show(view, scrollTarget, jump){
  view = PAGE;
  const changed = false;
  document.querySelectorAll('nav.main a').forEach(a=>{ if(a.dataset.go===view) a.setAttribute('aria-current','page'); else a.removeAttribute('aria-current'); });
  const t = scrollTarget && document.querySelector(scrollTarget);
  /* A new page jumps straight to its spot (a smooth scroll gets cut short while the page swaps in); same-page links still glide */
  const how = (changed || jump) ? 'instant' : 'smooth';
  if(t){ requestAnimationFrame(()=>t.scrollIntoView({behavior:how,block:'start'})); }
  document.body.dataset.view = view;
  revealCheck();
  requestAnimationFrame(()=>{ if(typeof paintHead==='function') paintHead(); });
  if(view==='home') requestAnimationFrame(()=>{ drawFlow(); paintScene(SX[jK]-42); });
}
function currentView(){ return PAGE; }
document.addEventListener('click', e=>{
  const a = e.target.closest('[data-go],[data-scroll]');
  if(!a) return;
  if(a.dataset.go && a.dataset.go !== PAGE) return; /* another page: let the browser load it */
  if(e.metaKey || e.ctrlKey || e.shiftKey) return;
  e.preventDefault();
  const fromMenu = !!a.closest('#mnav'); /* menu links jump straight there: a glide is cut short as the menu closes */
  closeMenus();
  if(a.closest('dialog')) document.getElementById('claimDlg').close();
  const go = a.dataset.go;
  let sc = a.dataset.scroll || (a.hasAttribute('data-claim-scroll') ? null : null);
  if(go && !sc){
    window.scrollTo({top:0,behavior:fromMenu?'instant':'smooth'});
  } else if(sc){
    const t=document.querySelector(sc); if(t) t.scrollIntoView({behavior:fromMenu?'instant':'smooth',block:'start'});
  }
});

