/* ---------- Reviews: one large card, progress bars underneath ---------- */
const RV_IMG=['img/breakdown.jpg','img/car.jpg','img/fleet.jpg'], RV_POS=['20% 60%','30% 45%','70% 50%'];
document.querySelectorAll('[data-reviews]').forEach(el=>{
  el.className='rv';
  el.innerHTML = `<div class="rv-stage">${REVIEWS.map((r,i)=>`<figure class="rv-card${i?'':' on'}" style="--img:url('${RV_IMG[i%3]}');--pos:${RV_POS[i%3]}"><span class="rv-chip">Google review</span><blockquote>“${r.q}”</blockquote><figcaption><b>${r.n}</b><span class="stars" aria-label="5 out of 5 stars">★★★★★</span></figcaption></figure>`).join('')}</div><div class="rv-bars">${REVIEWS.map((r,i)=>`<button type="button" class="${i?'':'on'}" aria-label="Show review ${i+1} of ${REVIEWS.length}"><i></i></button>`).join('')}</div>`;
  const cards=[...el.querySelectorAll('.rv-card')], bars=[...el.querySelectorAll('.rv-bars button')]; let k=0, t;
  const go=n=>{ k=(n+cards.length)%cards.length; cards.forEach((c,i)=>c.classList.toggle('on',i===k)); bars.forEach((b,i)=>b.classList.toggle('on',i===k)); };
  const play=()=>{ clearInterval(t); if(!matchMedia('(prefers-reduced-motion: reduce)').matches) t=setInterval(()=>{ if(el.offsetParent) go(k+1); },6000); };
  bars.forEach((b,i)=>b.addEventListener('click',()=>{ go(i); play(); }));
  play();
});

/* ---------- Journey: the chosen stage is the single source of truth ---------- */
const CLAIM = [
  {t:'Claim reported', d:'One call, details taken', w:'Mon 09:41', s:'Reported'},
  {t:'Cover and liability checked', d:'Bolton claims team', w:'Mon 11:30', s:'Being assessed'},
  {t:'Replacement vehicle delivered', d:'Repair booked at an approved repairer', w:'Mon 15:20', s:'In repair'},
  {t:'Uninsured losses recovered', d:'Excess and costs claimed back', w:'Day 19', s:'Recovering losses'},
  {t:'Claim settled', d:'Each step explained as it happens', w:'Day 24', s:'Settled'},
  {t:'Aftercare call', d:'We check in once it\'s done', w:'Day 25', s:'Closed, aftercare done'}
];
const VIEW = {
  customer:['Customer view','Broker and customer updated at every step'],
  broker:['Broker view','Settlement and outcome visible in the broker portal'],
  fleet:['Fleet manager view','Costs, durations and outcomes logged for your monthly MI pack']
};
const jg=document.getElementById('journeyGrid'), clSteps=document.getElementById('clSteps'), clFeed=document.getElementById('clFeed');
let jK=0, jAud='customer';
function renderJourney(aud){
  jAud=aud;
  jg.innerHTML = JOURNEY.map((s,k)=>`<button type="button" class="tab" role="tab" data-k="${k}"><span class="tab-n">0${k+1}</span><span class="tab-t">${s.h}</span><span class="tab-d">${s[aud]}</span><span class="tab-bar" aria-hidden="true"><i></i></span></button>`).join('');
  document.getElementById('clView').textContent = VIEW[aud][0];
  document.getElementById('clFoot').textContent = VIEW[aud][1];
  setStage(jK);
}
if(jg){ /* home page only */
clSteps.innerHTML = JOURNEY.map((s,k)=>`<button type="button" class="cl-step" data-k="${k}" aria-label="Stage ${k+1} of 6: ${s.h}"><span class="ic"><svg aria-hidden="true"><use href="#${s.i}"/></svg></span><span class="lb">${s.h}</span></button>`).join('');
clFeed.innerHTML = CLAIM.map(c=>`<li><span class="cl-dot"><svg aria-hidden="true"><use href="#i-check"/></svg></span><span><b>${c.t}</b><small>${c.d}</small></span><time>${c.w}</time></li>`).join('');
function setStage(k){
  const prev=jK;
  jK=(k+JOURNEY.length)%JOURNEY.length;
  const fwd=jK>=prev, dl=i=>Math.max(0, fwd ? i-prev-1 : prev-i)*120+'ms';
  const state=i=>i<jK?'done':i===jK?'now':'next';
  jg.querySelectorAll('.tab').forEach((b,i)=>{ b.classList.toggle('on',i===jK); b.setAttribute('aria-selected',String(i===jK)); });
  [...clSteps.children].forEach((b,i)=>{ b.style.setProperty('--dl',dl(i)); b.className='cl-step '+state(i); b.setAttribute('aria-current', i===jK ? 'step' : 'false'); });
  [...clFeed.children].forEach((li,i)=>{ li.style.setProperty('--dl',dl(i)); li.className=state(i); });
  const pill=document.getElementById('clPill'), changed=pill.textContent!==CLAIM[jK].s;
  pill.textContent=CLAIM[jK].s; pill.className='pill '+(jK>=4?'pill-done':'pill-live');
  if(changed){ void pill.offsetWidth; pill.classList.add('swap'); }
}
/* auto-play: the gold line under the open stage fills, then the next stage opens.
   Hovering pauses it (CSS); choosing a stage yourself stops it for good. */
const jSec=document.getElementById('journey'), jRow=jSec.querySelector('.tabs-row');
let jResume;
const stopPlay=()=>{
  jg.classList.remove('playing'); jSec.classList.add('manual');
  clearTimeout(jResume);
  jResume=setTimeout(()=>{ jSec.classList.remove('manual'); jg.classList.add('playing'); },8000);
  requestAnimationFrame(()=>requestAnimationFrame(()=>cursorTo(jK)));
};
jg.addEventListener('animationend',e=>{ if(e.target.closest('.tab-bar') && jg.classList.contains('playing')) autoNext(); });
jg.addEventListener('click',e=>{ const b=e.target.closest('.tab'); if(b){ stopPlay(); setStage(+b.dataset.k); } });
clSteps.addEventListener('click',e=>{ const b=e.target.closest('.cl-step'); if(b){ stopPlay(); setStage(+b.dataset.k); } });
jg.addEventListener('keydown',e=>{ if(e.key==='ArrowDown'||e.key==='ArrowUp'){ e.preventDefault(); stopPlay(); setStage(jK+(e.key==='ArrowDown'?1:-1)); jg.querySelectorAll('.tab')[jK].focus(); } });
document.querySelectorAll('[data-aud]').forEach(b=>b.addEventListener('click',()=>{
  document.querySelectorAll('[data-aud]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));
  renderJourney(b.dataset.aud);
  requestAnimationFrame(()=>cursorTo(jK,true));
}));
renderJourney('customer');

/* the pointer glides to the next stage, presses, and only then does the stage open */
const cur=document.createElement('div'); cur.className='fake-cursor'; cur.setAttribute('aria-hidden','true');
cur.innerHTML='<svg viewBox="0 0 24 24"><path d="M5 2.500v16.500l4.400-4 3 6.800 2.700-1.200-3-6.700h6z" fill="#fff" stroke="#15130b" stroke-width="1.400" stroke-linejoin="round"/></svg><i></i>';
jRow.append(cur);
function cursorTo(k,instant){
  const t=jg.querySelectorAll('.tab')[k]; if(!t) return;
  const a=jRow.getBoundingClientRect(), b=t.querySelector('.tab-t').getBoundingClientRect(), r=t.getBoundingClientRect();
  if(instant){ cur.style.transition='none'; }
  cur.style.transform='translate('+(r.right-a.left-28)+'px,'+(b.top-a.top+b.height*0.6)+'px)';
  if(instant){ void cur.offsetWidth; cur.style.transition=''; }
}
let jBusy=false;
function autoNext(){
  if(jBusy) return; jBusy=true;
  const next=(jK+1)%JOURNEY.length;
  cursorTo(next);
  setTimeout(()=>{
    if(!jg.classList.contains('playing')){ jBusy=false; return; }
    cur.classList.add('click');
    setTimeout(()=>{
      cur.classList.remove('click');
      if(jg.classList.contains('playing')){ setStage(next); requestAnimationFrame(()=>cursorTo(next)); }
      jBusy=false;
    },200);
  },560);
}
requestAnimationFrame(()=>cursorTo(jK,true));
addEventListener('resize',()=>cursorTo(jK,true));
document.fonts && document.fonts.ready.then(()=>cursorTo(jK,true));
}

