/* ---------- EDI connector lines ---------- */
const flow=document.querySelector('.flow');
function drawFlow(){
  if(!flow || flow.offsetParent===null) return;
  const old=flow.querySelector('svg.wires'); if(old) old.remove();
  if(innerWidth<=620) return;
  const fr=flow.getBoundingClientRect(), hub=flow.querySelector('.hub').getBoundingClientRect();
  const hx=hub.left-fr.left, hy=hub.top-fr.top+hub.height/2, hr=hub.right-fr.left;
  const ns='http://www.w3.org/2000/svg', svg=document.createElementNS(ns,'svg');
  svg.setAttribute('class','wires'); svg.setAttribute('aria-hidden','true');
  svg.setAttribute('viewBox',`0 0 ${fr.width} ${fr.height}`);
  let d='';
  flow.querySelectorAll('.sys:not(.out) div').forEach(b=>{const r=b.getBoundingClientRect(); const x=r.right-fr.left, y=r.top-fr.top+r.height/2; d+=`<path d="M${x} ${y} C${(x+hx)/2} ${y} ${(x+hx)/2} ${hy} ${hx} ${hy}"/>`;});
  flow.querySelectorAll('.sys.out div').forEach(b=>{const r=b.getBoundingClientRect(); const x=r.left-fr.left, y=r.top-fr.top+r.height/2; d+=`<path d="M${hr} ${hy} C${(x+hr)/2} ${hy} ${(x+hr)/2} ${y} ${x} ${y}"/>`;});
  svg.innerHTML=`<g class="base">${d}</g><g class="pulse">${d}</g>`;
  flow.prepend(svg);
}
addEventListener('resize',()=>{clearTimeout(drawFlow.t);drawFlow.t=setTimeout(drawFlow,120);});
document.fonts && document.fonts.ready.then(drawFlow);

/* ---------- Header: light text over dark sections, dark text over light ones ---------- */
const siteHead=document.querySelector('header.site');
const DARK='section.ink:not(.photo-band),section.proof,footer';
const pageFoot=document.querySelector('footer');
const calmMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
document.documentElement.classList.add('bgsw');
/* mark every section whose tone differs from the one before it */
document.querySelectorAll('main[data-view]').forEach(m=>{
  const secs=[...m.children].filter(e=>e.tagName==='SECTION');
  secs.forEach((sc,i)=>sc.classList.toggle('sheet', i>0 && sc.matches(DARK)!==secs[i-1].matches(DARK)));
});
let headRaf=0;
function paintHead(){
  if(headRaf) return;
  headRaf=requestAnimationFrame(()=>{
    headRaf=0;
    const main=document.querySelector('main[data-view]:not([hidden])');
    const secs=main ? [...main.children].filter(e=>e.tagName==='SECTION') : [];
    if(secs.length){
      pageFoot.classList.toggle('sheet', !secs[secs.length-1].matches(DARK));
      secs.push(pageFoot);
      const hb=siteHead.getBoundingClientRect().bottom, vh=innerHeight; let cur=secs[0], entering=null;
      for(const sc of secs){
        const top=sc.getBoundingClientRect().top;
        if(top<=hb) cur=sc;
        if(sc.classList.contains('sheet')){
          const p=calmMotion ? 1 : Math.min(1,Math.max(0,(vh-top)/(vh*0.5)));
          sc.style.setProperty('--p',p.toFixed(3));
          if(p>0 && p<1) entering=sc;
        }
      }
      /* whatever shows around a sheet that is still widening must be the colour it is leaving */
      if(entering) document.body.style.backgroundColor = entering.matches(DARK) ? 'var(--paper)' : 'var(--ink)';
      siteHead.classList.toggle('on-dark', cur.matches(DARK));
    }
    siteHead.classList.toggle('scrolled', scrollY>8);
  });
}
addEventListener('scroll',paintHead,{passive:true});
addEventListener('resize',paintHead);

/* ---------- Drop-downs: our own list in place of the browser's ---------- */
document.querySelectorAll('select').forEach((sel,n)=>{
  const dark = !!sel.closest('.chooser');
  const wrap = document.createElement('div'); wrap.className = 'dd' + (dark ? ' dd-dark' : '');
  const lab = sel.id && document.querySelector('label[for="'+sel.id+'"]');
  const id = 'dd'+n;
  wrap.innerHTML = '<button type="button" class="dd-btn" id="'+id+'" role="combobox" aria-haspopup="listbox" aria-expanded="false" aria-controls="'+id+'l"><span class="dd-val"></span><svg class="caret" aria-hidden="true"><use href="#i-caret"/></svg></button><ul class="dd-list" id="'+id+'l" role="listbox" tabindex="-1" hidden></ul>';
  sel.after(wrap); sel.classList.add('dd-native'); sel.tabIndex = -1; sel.setAttribute('aria-hidden','true');
  const btn = wrap.querySelector('.dd-btn'), val = wrap.querySelector('.dd-val'), list = wrap.querySelector('.dd-list');
  const opts = [...sel.options]; let act = sel.selectedIndex;
  list.innerHTML = opts.map((o,i)=>'<li role="option" id="'+id+'o'+i+'" data-i="'+i+'"><span>'+o.textContent+'</span><svg class="tick" aria-hidden="true"><use href="#i-check"/></svg></li>').join('');
  const items = [...list.children];
  const labelText = lab ? lab.textContent.replace(/\s+/g,' ').trim() : (sel.getAttribute('aria-label') || 'Choose an option');
  const paint = () => { val.textContent = opts[sel.selectedIndex].textContent; btn.setAttribute('aria-label', labelText + ': ' + val.textContent);
    items.forEach((li,i)=>{ li.setAttribute('aria-selected', String(i===sel.selectedIndex)); li.classList.toggle('act', i===act); });
    btn.setAttribute('aria-activedescendant', id+'o'+act); };
  const open = () => { if(!list.hidden) return; act = sel.selectedIndex; list.hidden = false; wrap.classList.add('open'); btn.setAttribute('aria-expanded','true'); paint(); items[act].scrollIntoView({block:'nearest'}); };
  const close = () => { list.hidden = true; wrap.classList.remove('open'); btn.setAttribute('aria-expanded','false'); };
  const pick = i => { sel.selectedIndex = i; act = i; sel.dispatchEvent(new Event('change',{bubbles:true})); paint(); close(); btn.focus(); };
  btn.addEventListener('click', () => list.hidden ? open() : close());
  list.addEventListener('click', e => { const li = e.target.closest('li'); if(li) pick(+li.dataset.i); });
  list.addEventListener('mousemove', e => { const li = e.target.closest('li'); if(li && +li.dataset.i!==act){ act = +li.dataset.i; paint(); } });
  btn.addEventListener('keydown', e => {
    const k = e.key;
    if(k==='ArrowDown' || k==='ArrowUp'){ e.preventDefault(); if(list.hidden) open(); else { act = (act + (k==='ArrowDown'?1:-1) + items.length) % items.length; paint(); items[act].scrollIntoView({block:'nearest'}); } }
    else if(k==='Enter' || k===' '){ e.preventDefault(); list.hidden ? open() : pick(act); }
    else if(k==='Escape' && !list.hidden){ e.preventDefault(); close(); }
    else if(k==='Tab') close();
    else if(k==='Home' && !list.hidden){ e.preventDefault(); act = 0; paint(); }
    else if(k==='End' && !list.hidden){ e.preventDefault(); act = items.length-1; paint(); }
  });
  document.addEventListener('click', e => { if(!wrap.contains(e.target)) close(); });
  if(lab) lab.addEventListener('click', e => { e.preventDefault(); btn.focus(); });
  paint();
});

/* ---------- Promise tiles: animate only while in view ---------- */
document.querySelectorAll('.tiles3').forEach(el=>{
  if(!('IntersectionObserver' in window)){ el.classList.add('live'); return; }
  new IntersectionObserver(es=>es.forEach(e=>el.classList.toggle('live', e.isIntersecting)),{threshold:.3}).observe(el);
});

/* ---------- Claim panel: entrance + only play while on screen ---------- */
(()=>{
  const sec=document.getElementById('journey'), panel=sec && sec.querySelector('.panel.claim');
  if(!panel) return;
  if(!('IntersectionObserver' in window)){ panel.classList.add('in'); sec.classList.add('inview'); return; }
  new IntersectionObserver(es=>es.forEach(e=>{ if(e.isIntersecting) panel.classList.add('in'); }),{threshold:.2}).observe(panel);
  new IntersectionObserver(es=>es.forEach(e=>{ sec.classList.toggle('inview', e.isIntersecting); if(e.isIntersecting) requestAnimationFrame(()=>cursorTo(jK,true)); }),{threshold:.12}).observe(sec);
})();

/* ---------- Dashboards: build themselves the first time they are seen ---------- */
(()=>{
  const calm = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const countUp = el => {
    const m = el.textContent.match(/^([^\d]*)([\d,]*\.?\d+)(.*)$/); if(!m) return;
    const pre=m[1], raw=m[2], post=m[3], target=parseFloat(raw.replace(/,/g,'')), dec=(raw.split('.')[1]||'').length, commas=raw.includes(',');
    const fmt=v=>pre+(commas ? Math.round(v).toLocaleString('en-GB') : v.toFixed(dec))+post, t0=performance.now(), dur=1300;
    const tick=t=>{ const p=Math.min(1,(t-t0)/dur), e=1-Math.pow(1-p,3); el.textContent=fmt(target*e); if(p<1) requestAnimationFrame(tick); else el.textContent=pre+raw+post; };
    requestAnimationFrame(tick);
  };
  const boards=[...document.querySelectorAll('.app,.tile-mock')];
  if(calm || !('IntersectionObserver' in window)){ boards.forEach(b=>b.classList.add('seen')); return; }
  const io=new IntersectionObserver(es=>es.forEach(e=>{
    const b=e.target; b.classList.toggle('live', e.isIntersecting);
    if(e.isIntersecting && !b.classList.contains('seen')){ b.classList.add('seen'); b.querySelectorAll('.kpi b').forEach(countUp); }
  }),{threshold:.2});
  boards.forEach(b=>io.observe(b));
})();

/* ---------- EDI flow: a short story on a loop, only while it is on screen ---------- */
document.querySelectorAll('.pipe').forEach(p=>{
  if(matchMedia('(prefers-reduced-motion: reduce)').matches || !('IntersectionObserver' in window)) return;
  const [c1,l1,hub,l2,c3]=p.children, logos=[...p.querySelectorAll('.pipe-logos span')], outs=[...p.querySelectorAll('.pipe-out li')];
  let timers=[], n=0, running=false;
  const at=(ms,fn)=>timers.push(setTimeout(fn,ms));
  const reset=()=>{ [c1,hub,c3].forEach(e=>e.classList.remove('lit')); [l1,l2].forEach(e=>e.classList.remove('go','done')); logos.forEach(e=>e.classList.remove('pick')); outs.forEach(e=>e.classList.remove('ok')); };
  const cycle=()=>{
    reset(); p.classList.add('run');
    at(350,()=>{ c1.classList.add('lit'); logos[n%logos.length].classList.add('pick'); });   /* 1 a quote starts in one of the three systems */
    at(1700,()=>l1.classList.add('go'));                                                       /*   it travels by EDI */
    at(2600,()=>{ l1.classList.remove('go'); l1.classList.add('done'); hub.classList.add('lit'); });  /* 2 BDElite quotes and binds */
    at(3800,()=>l2.classList.add('go'));
    at(4700,()=>{ l2.classList.remove('go'); l2.classList.add('done'); c3.classList.add('lit'); });   /* 3 the three outcomes tick off */
    outs.forEach((li,i)=>at(5000+i*480,()=>li.classList.add('ok')));
    at(8800,()=>{ n++; cycle(); });
  };
  const stop=()=>{ timers.forEach(clearTimeout); timers=[]; p.classList.remove('run'); reset(); };
  new IntersectionObserver(es=>es.forEach(e=>{
    if(e.isIntersecting && !running){ running=true; cycle(); }
    else if(!e.isIntersecting && running){ running=false; stop(); }
  }),{threshold:.35}).observe(p);
});


